tests['Response status is 200'] = response.status === 200;

// Check response contains expected data
tests['Response contains expected data'] = response.body && response.body.success === true;

// Check response headers
tests['Response has content-type header'] = response.headers && response.headers['content-type'] && response.headers['content-type'].includes('application/json');

// Check response status
